import{_ as a,c as e,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const m=JSON.parse('{"title":"西溪易說卷三","description":"西溪易說 - 西溪易說卷三","frontmatter":{"title":"西溪易說卷三","description":"西溪易說 - 西溪易說卷三"},"headers":[],"relativePath":"classics/xixi/004.md","filePath":"classics/xixi/004.md"}'),i={name:"classics/xixi/004.md"};function r(c,p,_,o,n,l){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="西溪易說卷三" tabindex="-1">西溪易說卷三 <a class="header-anchor" href="#西溪易說卷三" aria-label="Permalink to “西溪易說卷三”">​</a></h1><p>欽定四庫全書</p><p>宋李過撰</p><p>䷊ 乾下坤上</p><p>泰，</p><p>泰：小往大來，吉亨。彖曰：「泰：小往大來，吉亨」。則是天地交而萬物通也，上下交而其志同也。內陽而外陰，內健而外順，內君子而外小人，君子道長，小人道消也。論天地之位，則乾上而坤下；論天地之交，則天氣必下降，地氣必上騰。天地之氣交，然後生萬物。故論天地之交，則必乾下而坤上，是天地之氣交也，其卦為泰，三陽在內，三陰在外；陽為君子，陰為小人。治世則君子在內，小人在外也。內健而外順，內剛而外柔，又君子之道也。蓋小人之道，色厲而外荏，與君子相反，故泰卦為君子道長之義。曰：「小往大來，吉亨」，小者往而居外，謂陰消也；大者來而居內，謂陽長也。陰消陽長，君子之道，吉者亨也。然太平之功固難居，六爻反覆言所以處太平之道，彖辭義甚明。</p><p>象曰：天地交，泰；後以財成天地之道，輔相天地之宜，以左右民。</p><p>天地交而生萬物，必聖人財成輔相之而後可。天地之力有不及，必聖人財成之，如穿牛絡馬之類。天地之道有當然，必聖人輔相之，如春耕夏耘之類。天人之際本和同，然不能以詔乎民，民不能以授於天，聖人財成輔相之功，所以左右乎民也。</p><p>初九，拔茅茹，以其匯，徵吉。象曰：「拔茅徵吉」，志在外也。時泰，則賢者可以引類而進，志在外，應五也。</p><p>九二，包荒，用馮河，不遐遺，朋亡，得尚於中行。象曰：「得尚於中行」，以光大也。</p><p>九二臣位，當泰之世，君子在內而小人在外，為大臣者，必得所以處君子小人之道。君子固當用小人，亦不可使之失所也。「包荒，用馮河」，用君子之道也。用賢之道貴廣，當明時不可有棄才，一智一能，皆得自效，馮河之勇者，亦得用也。「不遐遺，朋亡」，處小人之道也。遐，遠也。小人遠而在外，不當冇厭棄之意。疾惡太甚，則小人之怨生矣。朋亡，善惡不可立黨，黨立則相傾而亂生。此皆鈞軸天下者之任也，故於九二言之。「得尚於中行」。言鈞軸天下者能如此，然後可以上任六五之責也。象曰「以光大也」，正所謂如有一個臣，斷斷兮無他技，其心休休焉，其如有容焉，以保我子孫黎民也。前世朋黨之禍，皆起於君子不善處小人之故。</p><p>九三，無平不陂，無往不復，艱貞無咎。勿恤其孚，於食有福。象曰：「無往不復」，天地際也。</p><p>三居下體之上，上下之交，否、泰相反之際也。三陽既極，陰道將反，聖人預為之戒曰：「無平不陂，無往不復。」天下之理，無常安平而不險陂者，謂無常泰也；無常往、往而不返者，謂陰當復也。君子處此，當知致治之艱難而謹之則吉。雖然，小人將復，「否」之憂也。吾君臣相信之深，無隙之可投，則小人何所容其奸？君臣相孚，則於食有福也。前世小人乘間，多起於君臣不相信。象曰「天地際也」，此言泰否之交也。</p><p>六四，翩翩，不富以其鄰，不戒以孚。象曰：「翩翩」「不富」，皆失實也。「不戒以孚」，中心願也。</p><p>以卦之內外言之，陽內而陰外；以卦之上下言之，陽下而陰上，是小人猶在上也，將使之不有其孚，以其鄰翩翩而下，退聽以避賢者路，則必有感服其心而後可，非告戒所能令也。故治世君子必有以服小人之心，而使之自不為亂，非必盡去其黨也。象曰「中心願也」，言小人之服，當自出小人之心然後可也。司馬溫公處元祐間事，正坐此。</p><p>六五，帝乙歸妹，以祉元吉。象曰：「以祉元吉」，中以行願也。五，「泰」之主也。天地交則為「泰」，君臣交則為「泰」。君臣交際，莫大於「歸妹」。古者王姬下嫁諸侯，五歸妹而二尚主，父際之盛。「以祉元吉」，祉，福也，言錫福於二也。象曰「中以行願也」，言君臣之交，出於中心之誠也。</p><p>上六，城復於隍，勿用師，自邑告命，貞吝。象曰：「城復於隍」，其命亂也。</p><p>泰極則否，理所必至，「城復於隍」矣。濬隍之土以築城，今城之土又復於隍，弊壞之象也。太平之禍，多起用兵，當此之時，何暇遠略？退治吾國可也。故曰：「勿用行師，自邑告命。」若貞守初意，則吝。象曰「其命亂也」，言否將至也。䷋ 坤下乾上</p><p>「否」，</p><p>否之匪人，不利君子貞，大往小來。彖曰：</p><p>「否之匪人，不利君子貞，大往小來」，則是天地不交而萬物不通也，上下不交而天下無邦也。內陰而外陽，內柔而外剛，內小人而外君子。小人道長，君子道消也。</p><p>否，泰之反，彖辭皆與泰反。乾上坤下，是天地不交，不生萬物，閉塞而成冬之時也。小人居內，君子居外，是小人道長，君子道消。又內柔而外剛，內健而外順，皆小人之道。曰「否之匪人」，天下不幸，至於大弊極壞，而非人為之咎，則天數也，然後可以言否。不然，禍亂自己致，而歸咎於天命，則非陰陽消長自然之理，故曰「否之匪人」，言非由人致也。蓋禍亂出於天，修人事以應之，天命尚可回，出於人則不可逭矣。不利君子貞。小人道長，故不利君子之正也。彖辭「天下無邦」，蓋大亂之世，下陵上替，不復能事君。象曰：天地不交，「否」，君子以儉德避難，不可榮以祿居子，處亂世之道也。</p><p>初六：拔茅茹，以其匯，徵吉亨。象曰：拔茅貞吉，志在君也。時既否，君子引其類而退則吉。既否矣，安得亨？然必曰「亨」者，無終否之理。君子所性，盛行不加，窮居不損，眾人以為否，君子未嘗不亨也。象曰：「志在君也。」君子雖退，心未嘗一日不在君，所謂「中心藏之，何日忘之」是也。六二：包承，小人吉，大人否，亨。象曰：「大人否亨」，不亂群也。當否之時，小人在內，君子皆奉身而退，則國何所倚？九五能休否之君，二得其應，君臣之情猶孚也，故包承而不去。夫包承於群小之間，小人固吉，大人固否，然實則亨也。他時所賴抗群小而君子之道復還者，皆今日不去之力也。象曰：不亂群也。處群小之間而不為所亂，大人之事也。王文正公用此爻。</p><p>六曰：包羞。象曰：「包羞」，位不當也。三不中正，處尊位而不去，苟祿者也。故曰漢張禹、孔光，五代馮道其流也。若為貧而仕，抱關擊柝可也，安用據上位哉？故象曰：「包羞，位不當也。」</p><p>九四：有命無咎，疇離祉。象曰：「有命無咎」，志行也。</p><p>此天道之一變也。易為君子慮，不為小人謀。天道一變，三陽將復，君子之道復還矣。謂君子曰：「天命未艾，無我尤也，天將福吾類矣。」蓋為君子喜也。象曰「志行也」，君子將得行其志也。九五：休否，大人吉。其亡其亡，繋於苞桑。象曰：「大人」之「吉」，位正當也。</p><p>九五陽剛之德，能「休否」者也。大人「否」於二，至此吉可知矣。雖然，三陰猶在內，小人未盡去位也，不可以不謹，故曰：「其亡其亡，繫於苞桑。」如其以身託於苞桑然。桑，柔脆之木也。方苞之桑，又柔脆之甚，危之至也，常若危亡之在旦夕也。古之人主，禍難才平而安意肆志，若唐德宗、憲宗者多矣。繫辭曰：「危者，安其位者也；亡者，保具存者也；亂者，有其治者也。是故君子安而不忘危，存而不忘亡，治而不忘亂，是以身安而國家可保也。」易曰：「其亡其亡，繫於苞桑。」</p><p>上九：傾否，先否後喜。象曰：否終則傾，何可長也。</p><p>物極必反，故上九「傾否」，「否」則泰來矣。泰極則「否」，否極則喜，豈有長否之理？反危為安，易治為亂，必有陽剛之才而後能也。故「否」之上九則能傾否，屯之上六則不能變屯也。䷣ 離下乾上 同人，</p><p>同人於野，亨。利涉大川，利君子貞。彖曰：同人，柔得位得中而應乎乾，曰「同人」。同人曰</p><p>「同人於野，亨，利涉大川」，乾行也。文明以健，中正而應，君子正也。惟君子為能通天下之志，</p><p>天理一而已矣，無往而不同也。天下之人，所稟各異，等倫則相絕也。然其中有不約而同者，即天理之一也。目有同視，耳有同聽，至於心，獨無所同然乎？此同人所以名卦也。然其理甚隱。卦體一陰在二，五陽皆欲同也，是舉天下皆知子都之姣者也。人心至一處也，然非五陽之同，皆能同也。六爻有正應之同，二、五以正應而同，上下四陽皆退聽。其始之慾同者，天理之同也；其終之退聽者，亦天理之同也。此聖人設同人之義也。卦辭雲：「同人於野，亨。」無往而不同，此理也。利涉大川，同舟遇風波，胡越共濟，此可以見同也。利君子貞。君子一理同，是正同也。彖曰：「柔得位得中，而應乎乾，曰同人。」柔居二而得中，上應乾體之九五，得正應之同，故曰「同人」也。曰「同人於亨。野，利涉大川，乾行也」。在野而同，共舟而同，天理不約而同，故曰「乾行」也。文明以健，中正而應，君子正也。以一陰在二，五陽之所欲同也。然一陰雖五陽所欲同也，非正應之同，終不能同。下體文明，上體剛健，中之以二為文明之中，五為剛健之中，剛柔正應，君子之正同也。惟以正同，則天下無往而不合，向之慾同者，莫不退聽也，故曰：「唯君子為能通天下之志。」以六爻言之，初出門遇二而同，三伏戎近二而同，四乘墉望二而同，上處郊，遠二而同。此非正應而同，終不克同也，故上止無咎。三不敢與，四不敢攻上，志未得終也。五克眾陽而遇二，二去其宗而同五，二爻相遇，蘭臭交契，誠發乎中，達於面目，先之以泣，而繼之以喜也。蓋其同也以正，而眾陽之所同退聽也。故繫辭贊之曰：「二人同心，其利斷金；同心之言，其臭如蘭。」天理顯矣。象曰：天與火，同人，君子以類族辨物。</p><p>天在上，火炎上，氣類之同，是同人之象也。君子觀此，則「類族辨物」。萬物之上同乎一氣，然而群分而類聚。君子於天下有大同之理，然須有個差等，內外親疏、小大遠近，雖差不同，所以有至同也。不然，便是墨子之愛，故貴於類族而辨物。</p><p>初九，同人於門，無咎。象曰：出門同人，又誰咎也！</p><p>一陰在二，眾陽所欲同也。初近之，出門而相遇，故曰「同人於門」。相遇而同，又誰咎也！</p><p>六二，同人於宗，吝。象曰：「同人於宗」，吝道也。</p><p>眾陽皆欲同二，二未應五，與下體同，同於宗也，然非正，故「吝」。</p><p>九三，伏戎於莽，升其高陵，三歲不興。象曰：「伏戎於莽」，敵剛也。「三歲不興」，安行也！</p><p>三欲同二而懼五，故「伏戎於草莽，又升其高陵」以窺伺，然正理不容，故三歲不敢興。三取五隔三爻，故曰「三歲」。象曰「敵剛也」，「剛」謂五也。「三歲不興，安行也？」知其非是，退而順理也。</p><p>九四，乘其墉，弗克攻，吉。象曰：「乘其墉」，義弗克也。其吉，則困而反則也。</p><p>四欲同二而隔九三，故乘九三之墉。然義弗克攻也，故從義而吉。象曰「困而反則也」，困憊而反乎天理也，則，天理之不可逾越者也。觀三、四二爻，見天理在人，不可泯沒。九五：同人，先號啕而後笑，大師克相遇。象曰：同人之先，以中直也。大師相遇，言相剋也。</p><p>五與二同，本正應也，為三四所間，二又與下體同，故必欲用大師以先下三陽，然後得與二相遇。凡人久闊而會面，未有不垂泣者，其中心之誠不約而然也。故「先號啕而後笑」，可以見同心之至。諸陽不能同二，而終與五同，此君子以理同也，同之正也。象曰：以中直也，中心達於而目而號啕。繫辭曰：「君子之道，或出或處，或嘿或語。二人同心，其利斷金；同心之言，其臭如蘭。」</p><p>上九：同人於郊，無悔。象曰：「同人於郊」，志未得也。</p><p>二居內而九在郊，遠而不得同也。然本非己應，何悔之有？象曰「志未得也」，言未得遂其所同之志也。䷍ 乾下離上 大有，</p><p>大有，元亨。彖曰：大有，柔得尊位，大中而上下應之，曰「大有」。其德剛健而文明，應乎天而時行，是以「元亨」。大有，盛大富有之時也。離上乾下曰當中天，物無不照。柔當君位，五陽皆歸陽為富，天下之富皆歸五，富有四海之象也。卦辭雲：「大有，元亨。」天下富有亨通之時也。彖曰：「柔得尊位，大中而上下應之，曰大有。」謂上下五陽皆歸君也。柔居五，持盈守成之主也。乾下離上，其德剛健而文明，六爻皆善，天命祐之，應乎天而時行也，是以「元亨」。他卦如泰，如豫，如豐，如既濟，皆言治世事也，而六爻之變皆未盡善，唯大有六爻皆善，故卦無它辭，但曰「元亨」。夫子彖辭推原所以「元亨」之意，以二體有剛健文明之德，故動而皆善。六爻並吉，善處「大有」，以得天祐，是以「元亨」也。</p><p>象曰：火在天上，「大有」，君子以遏惡揚善，順天休命。天上有火，日火也。離日當天，萬物皆相見之時，盛多之象也。當太平之世，幸門易啟，一小人用，則足以虧「大有」之功。故君子體離照之象，遏惡揚善，以順天休命。蓋天意生賢，所以佑「大有」之君也；而遏惡揚善，所以順承天之休命也。開元太平之盛，罷張相李，而亂階已成，非天不相唐，唐之君無以受天命也。</p><p>初九，無交害，匪咎，艱則無咎。象曰：大有初九，無交害也。人君一心，攻之者甚眾。既居「大有」之始，好惡未萌，眾說雜然以投，皆害人主之心術者也。投而中，則「大有」之志荒矣，故於初爻便戒之「無交害」。不交其害，則投者去矣，故「匪咎」。然好大喜功，人主易有此也，惟思念祖宗所以致此之艱難，則不敢輕試矣，故曰「艱則無咎」。象曰：大有初九，無交害也。言當察之於初也。正如武帝承文、景富庶之後，開邊禮神，祥瑞萬物，皆足以中其欲，則虛耗之形見矣。</p><p>九二，大車以載，有攸往，無咎。象曰：「大車以載」，積中不敗也。</p><p>九二以陽剛之才居臣位，能任矢下之重，五為正應，能推誠而尚賢，君臣相與以濟「大有攸往」而「無咎」也。象曰「積中不敗也」，言克負荷「大有」之責也。九三，公用亨於天子，小人弗克。象曰：「公用亨於天子」，小人害也。</p><p>三居下卦之上，諸侯之位也。「大有」之世，眾陽皆歸五，三而歸五，諸侯覲王之象也。諸侯以其國之富貢於天子也，故曰「公用亨於天子」。若小人處此，則多斂巧取以逢人主之慾矣，故曰「小人弗克」。後世日進月進，皆小人之逢君者也，而民亦困矣，故象曰小人害也。</p><p>九四，匪其彭，無咎。象曰：「匪其彭無咎」，明辨晳也。四陽歸五，其富極矣。才有其富，侈心便生，故曰「匪其彭」。彭，大也，不自有其大，則「無咎」也。象曰：「明辨晳也。」明見盛大之不可居，故不敢有其富也。四居離體，故其見明。</p><p>六五，厥孚交如，威如，吉。象曰：「厥孚交如」，信以發志也；「威如」之吉，易而無備也。</p><p>五以柔居尊位，處「大有」之世而居中，得大中之體者也。眾陽歸己，天下之富皆歸君，六五何以處之？以誠信之道受之可也，故曰「厥孚交如，威如」。然太平之世，禍患皆起於無虞，故必「威如」而後「吉」。才易玩則無備也。故詰戎兵，董正治官，皆守成之世所當講也。</p><p>上九，自天祐之，吉無不利。象曰：大有上吉，「自天祐」也。合大有一卦，六爻皆善，初「無交害」，二「大以載」，三「用亨於天子」，四「匪其彭」，五「厥孚交如」，善處大有者也，宜其得天祐，故於上爻特贊之曰：「自天祐之，吉無不利。」總一卦而言之，非止謂上九也。繋辭曰：「天之所助者，順也；人之所助者，信也。履信思乎順，以尚賢也。是以自天祐之，吉無不利。」言五履信，四思順，二與三皆賢，得上交於五也。如此而後可以得天人之助。西溪易說卷三，</p>',54)])])}const x=a(i,[["render",r]]);export{m as __pageData,x as default};
